module multi_pipe_4bit #(
    parameter size = 4,
    parameter N = 2 * size
) (
    input 						clk,
    input 						rst_n,
    input	[size-1:0]			mul_a,
    input	[size-1:0]			mul_b,
    output	reg	[size*2-1:0]	mul_out
);

reg [size-1:0] reg_a;
reg [size-1:0] reg_b;
reg [size-1:0] partial_product;
reg [size*2-1:0] intermediate_result;
reg [7:0] sum_tmp1, sum_tmp2;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        reg_a <= 0;
        reg_b <= 0;
        mul_out <= 0;
        sum_tmp1 <= 0;
        sum_tmp2 <= 0;
    end else begin
        reg_a <= mul_a;
        reg_b <= mul_b;
        partial_product <= reg_a * reg_b[0];
        intermediate_result <= {intermediate_result[size*2-2:size], partial_product};

        sum_tmp1 <= (mul_b[0] ? mul_a : 0) + (mul_b[1] ? mul_a << 1 : 0);
        sum_tmp2 <= (mul_b[2] ? mul_a << 2 : 0) + (mul_b[3] ? mul_a << 3 : 0);

        mul_out <= sum_tmp1 + sum_tmp2;
    end
end

endmodule
